CREATE TABLE users(id uuid PRIMARY KEY,username varchar(100) UNIQUE NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('ADMIN','EDITOR','VIEWER','RELEASER')),active boolean NOT NULL DEFAULT true);
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users,expires_at timestamptz NOT NULL);
CREATE INDEX ON sessions(expires_at);
CREATE TABLE companies(id uuid PRIMARY KEY,code varchar(64) UNIQUE NOT NULL,name varchar(200) NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','ACTIVE','INACTIVE')),remark varchar(2000),address text,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL REFERENCES users,revision integer NOT NULL DEFAULT 1);
CREATE TABLE factories(LIKE companies INCLUDING DEFAULTS INCLUDING CONSTRAINTS,company_id uuid NOT NULL REFERENCES companies,PRIMARY KEY(id),UNIQUE(company_id,code),UNIQUE(id,company_id));
CREATE TABLE partners(LIKE companies INCLUDING DEFAULTS INCLUDING CONSTRAINTS,company_id uuid NOT NULL REFERENCES companies,contact_name varchar(200),phone varchar(100),supplier_capabilities text[] NOT NULL DEFAULT '{}',PRIMARY KEY(id),UNIQUE(company_id,code),UNIQUE(id,company_id),CHECK(supplier_capabilities <@ ARRAY['MATERIAL','PROCESSING']::text[]));
CREATE TABLE partner_roles(partner_id uuid REFERENCES partners ON DELETE RESTRICT,role text CHECK(role IN ('CUSTOMER','SUPPLIER')),status text NOT NULL CHECK(status IN ('ACTIVE','INACTIVE')),PRIMARY KEY(partner_id,role));
CREATE TABLE warehouses(LIKE companies INCLUDING DEFAULTS INCLUDING CONSTRAINTS,company_id uuid NOT NULL REFERENCES companies,factory_id uuid NOT NULL,location_type text NOT NULL DEFAULT 'INTERNAL' CHECK(location_type IN ('INTERNAL','SUPPLIER')),custodian_supplier_id uuid,PRIMARY KEY(id),UNIQUE(factory_id,code),UNIQUE(id,company_id,factory_id),FOREIGN KEY(factory_id,company_id) REFERENCES factories(id,company_id),FOREIGN KEY(custodian_supplier_id,company_id) REFERENCES partners(id,company_id),CHECK((location_type='INTERNAL' AND custodian_supplier_id IS NULL) OR (location_type='SUPPLIER' AND custodian_supplier_id IS NOT NULL)));
CREATE TABLE locations(LIKE companies INCLUDING DEFAULTS INCLUDING CONSTRAINTS,company_id uuid NOT NULL REFERENCES companies,factory_id uuid NOT NULL,warehouse_id uuid NOT NULL,usage_hint text NOT NULL DEFAULT 'GENERAL' CHECK(usage_hint IN ('GENERAL','RAW','WIP','FINISHED','QUARANTINE')),PRIMARY KEY(id),UNIQUE(warehouse_id,code),FOREIGN KEY(warehouse_id,company_id,factory_id) REFERENCES warehouses(id,company_id,factory_id));
CREATE TABLE units(LIKE companies INCLUDING DEFAULTS INCLUDING CONSTRAINTS,dimension text NOT NULL CHECK(dimension IN ('COUNT','MASS','LENGTH','VOLUME','OTHER')),decimal_places integer NOT NULL DEFAULT 0 CHECK(decimal_places BETWEEN 0 AND 6),PRIMARY KEY(id),UNIQUE(code));
CREATE TABLE material_categories(LIKE companies INCLUDING DEFAULTS INCLUDING CONSTRAINTS,company_id uuid NOT NULL REFERENCES companies,parent_id uuid,PRIMARY KEY(id),UNIQUE(company_id,code),UNIQUE(id,company_id),FOREIGN KEY(parent_id,company_id) REFERENCES material_categories(id,company_id));
CREATE TABLE materials(LIKE companies INCLUDING DEFAULTS INCLUDING CONSTRAINTS,company_id uuid NOT NULL REFERENCES companies,category_id uuid,material_kind text CHECK(material_kind IN ('RAW','SEMI','FINISHED')),specification text,base_unit_id uuid REFERENCES units,tracking_mode text NOT NULL DEFAULT 'BATCH' CHECK(tracking_mode IN ('NONE','BATCH','SERIAL','BATCH_SERIAL')),serial_uniqueness text CHECK(serial_uniqueness='MATERIAL'),PRIMARY KEY(id),UNIQUE(company_id,code),UNIQUE(id,company_id),FOREIGN KEY(category_id,company_id) REFERENCES material_categories(id,company_id));
CREATE TABLE material_units(material_id uuid REFERENCES materials,unit_id uuid REFERENCES units,factor numeric(20,6) NOT NULL CHECK(factor>0),PRIMARY KEY(material_id,unit_id));
CREATE TABLE material_factory_policies(id uuid PRIMARY KEY,company_id uuid NOT NULL,material_id uuid NOT NULL,factory_id uuid NOT NULL,allowed_supply_modes text[] NOT NULL,default_supply_mode text NOT NULL,allowed_production_strategies text[] NOT NULL DEFAULT '{}',default_production_strategy text,preferred_supplier_id uuid,status text NOT NULL CHECK(status IN ('ACTIVE','INACTIVE')),UNIQUE(material_id,factory_id),FOREIGN KEY(material_id,company_id) REFERENCES materials(id,company_id),FOREIGN KEY(factory_id,company_id) REFERENCES factories(id,company_id),FOREIGN KEY(preferred_supplier_id,company_id) REFERENCES partners(id,company_id),CHECK(cardinality(allowed_supply_modes)>0 AND allowed_supply_modes <@ ARRAY['BUY','MAKE','SUBCONTRACT']::text[] AND default_supply_mode=ANY(allowed_supply_modes)),CHECK(allowed_production_strategies <@ ARRAY['MTO','MTS']::text[]),CHECK((NOT (allowed_supply_modes && ARRAY['MAKE','SUBCONTRACT']::text[])) OR (cardinality(allowed_production_strategies)>0 AND default_production_strategy IS NOT NULL AND default_production_strategy=ANY(allowed_production_strategies))),CHECK(default_production_strategy IS NULL OR default_production_strategy=ANY(allowed_production_strategies)));
CREATE TABLE material_inspection_policies(policy_id uuid REFERENCES material_factory_policies,inspection_type text CHECK(inspection_type IN ('IQC','FQC','OQC')),requirement text NOT NULL CHECK(requirement IN ('REQUIRED','EXEMPT')),exemption_reason text,PRIMARY KEY(policy_id,inspection_type),CHECK((requirement='EXEMPT' AND exemption_reason IS NOT NULL AND length(trim(exemption_reason))>0) OR (requirement='REQUIRED' AND exemption_reason IS NULL)));
CREATE TABLE user_company_scopes(user_id uuid REFERENCES users,company_id uuid REFERENCES companies,PRIMARY KEY(user_id,company_id));
CREATE TABLE user_factory_scopes(user_id uuid REFERENCES users,factory_id uuid REFERENCES factories,PRIMARY KEY(user_id,factory_id));
CREATE TABLE audit_logs(id uuid PRIMARY KEY,actor_id uuid NOT NULL REFERENCES users,action text NOT NULL,entity_type text NOT NULL,entity_id uuid NOT NULL,company_id uuid,factory_id uuid,before_json jsonb,after_json jsonb,reason text,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON audit_logs(entity_type,entity_id,occurred_at);
CREATE INDEX ON audit_logs(company_id,factory_id);
